			var doc = this._doc;
			this._removeNodes(this._getAllNodesWithTag(doc, ["style"]));
			if (doc.body) this._replaceBrs(doc.body);
			this._replaceNodeTags(this._getAllNodesWithTag(doc, ["font"]), "SPAN");
